package id.imperial.resourcepack.paper;
import id.imperial.resourcepack.common.*;import net.kyori.adventure.text.minimessage.MiniMessage;import org.bukkit.entity.Player;import org.bukkit.event.*;import org.bukkit.event.player.PlayerJoinEvent;import org.bukkit.plugin.java.JavaPlugin;import java.io.*;import java.nio.file.*;import java.util.concurrent.*;
public final class ImperialResourcePackPaper extends JavaPlugin implements Listener {private final ExecutorService worker=Executors.newSingleThreadExecutor();private ResourcePackManager manager;private ResourcePackHost host;private volatile ResourcePackConfig config;@Override public void onEnable(){manager=new ResourcePackManager(getLogger());host=new ResourcePackHost(manager,getLogger());reload();getServer().getPluginManager().registerEvents(this,this);getCommand("irp").setExecutor(new PaperCommand(this));}@Override public void onDisable(){host.close();worker.shutdown();}@EventHandler public void join(PlayerJoinEvent e){ResourcePackConfig c=config;if(c!=null&&c.enabled()&&c.deliveryEnabled())getServer().getScheduler().runTaskLater(this,()->send(e.getPlayer()),Math.max(1,c.sendDelayMs()/50));}void send(Player p){ResourcePackConfig c=config;ActivePack a=manager.active();if(c==null||a==null||c.publicUrl().isBlank())return;p.setResourcePack(a.id(),c.publicUrl(),a.sha1(),MiniMessage.miniMessage().deserialize(c.prompt()),c.required());}synchronized String reload(){try{Path d=getDataFolder().toPath();Files.createDirectories(d);Path f=d.resolve("config.yml");if(Files.notExists(f))try(InputStream in=getResource("config.yml")){Files.copy(in,f);}config=ResourcePackConfig.load(f);Path packs=d.resolve(config.packsDirectory()).normalize();if(!packs.startsWith(d))return "Invalid packs-directory.";manager.scan(packs,config);host.start(config,worker);return "Reload complete.";}catch(Exception e){getLogger().severe(e.getMessage());return "Reload failed: "+e.getMessage();}}ResourcePackManager manager(){return manager;}ResourcePackHost host(){return host;}ResourcePackConfig config(){return config;}}
